content.query:
let draft = customEvents | where name in ("quote_drafted", "quote_failed") | summarize n = count(), p95_s = percentile(todouble(customDimensions.duration_ms), 95) / 1000, failed_pct = 100.0 * countif(name == "quote_failed") / count() | extend flow = "draft: extract, match, price";
let issue = requests | where name endswith "/review" or name endswith "/document" | summarize n = count(), p95_s = percentile(duration, 95) / 1000, failed_pct = 100.0 * countif(toint(resultCode) >= 500) / count() | extend flow = "issue: review, render, download";
union draft, issue
| extend state = case(n == 0, "no traffic", p95_s > 60 or failed_pct > 5, "unhealthy", p95_s > 45 or failed_pct > 1, "degraded", "healthy")
| project flow, state, requests = n, p95_s = round(p95_s, 1), failed_pct = round(failed_pct, 2)

let kpi1 = customEvents | where name == "quote_approved" | summarize kpi1_median_s = percentile(todouble(customDimensions.elapsed_s), 50), approved = count() by month = startofmonth(timestamp);
let kpi2 = customEvents | where name == "line_reviewed" | summarize kpi2_accepted_pct = round(100.0 * countif(tostring(customDimensions.outcome) == "accepted") / count(), 1) by month = startofmonth(timestamp);
let kpi3 = customEvents | where name == "feedback" | summarize kpi3_up_pct = round(100.0 * countif(tostring(customDimensions.value) == "up") / count(), 1), votes = count() by month = startofmonth(timestamp);
kpi1 | join kind=fullouter kpi2 on month | join kind=fullouter kpi3 on month
| project month = coalesce(month, month1, month2), approved, kpi1_median_s, kpi2_accepted_pct, kpi3_up_pct, votes
| order by month desc
